display.text:
import { IS_NON_DIMENSIONAL } from '../constants';
import options from '../options';

/**
 * Diff the old and new properties of a VNode and apply changes to the DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to apply
 * changes to
 * @param {object} newProps The new props
 * @param {object} oldProps The old props
 * @param {boolean} isSvg Whether or not this node is an SVG node
 * @param {boolean} hydrate Whether or not we are in hydration mode
 */
export function diffProps(dom, newProps, oldProps, isSvg, hydrate) {
	elementPropHost.diffAllProps(dom, newProps, oldProps, isSvg, hydrate);
}

/**
 * Set a property value on a DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to modify
 * @param {string} name The name of the property to set
 * @param {*} value The value to set the property to
 * @param {*} oldValue The old value the property had
 * @param {boolean} isSvg Whether or not this DOM node is an SVG node or not
 */
export function setProperty(dom, name, value, oldValue, isSvg) {
	elementPropHost.writeProperty(dom, name, value, oldValue, isSvg);
}

/**
 * Proxy an event to hooked event handlers
 * @param {Event} e The event object from the browser
 * @private
 */
function eventProxy(e) {
	this._listeners[e.type + false](options.event ? options.event(e) : e);
}

function eventProxyCapture(e) {
	this._listeners[e.type + true](options.event ? options.event(e) : e);
}

class ElementPropHost {
	constructor() {
		this._styleScratch = null;
		this._stylePrev = null;
		this._styleUnit = 'px';
		this._styleCustom = false;
		this._listenerScratch = null;
		this._captureMode = false;
		this._eventName = '';
		this._attrName = '';
		this._attrNs = '';
		this._attrBool = false;
		this._propScratch = null;
		this._pendingKey = null;
		this._pendingRef = null;
		this._cloneScratch = null;
		this._cloneKey = null;
		this._cloneRef = null;
		this._errorNode = null;
		this._errorHandled = false;
		this._errorCtor = null;
		this._compatName = '';
		this._compatValue = null;
		this._compatType = '';
		this._preparers = {
			accept: this.prepareAccept,
			acceptCharset: this.prepareAcceptCharset,
			accessKey: this.prepareAccessKey,
			action: this.prepareAction,
			allow: this.prepareAllow,
			allowFullScreen: this.prepareAllowFullScreen,
			alt: this.prepareAlt,
			async: this.prepareAsync,
			autoComplete: this.prepareAutoComplete,
			autoFocus: this.prepareAutoFocus,
			autoPlay: this.prepareAutoPlay,
			capture: this.prepareCapture,
			cellPadding: this.prepareCellPadding,
			cellSpacing: this.prepareCellSpacing,
			challenge: this.prepareChallenge,
			charSet: this.prepareCharSet,
			checked: this.prepareChecked,
			cite: this.prepareCite,
			className: this.prepareClassName,
			colSpan: this.prepareColSpan,
			cols: this.prepareCols,
			content: this.prepareContent,
			contentEditable: this.prepareContentEditable,
			controls: this.prepareControls,
			coords: this.prepareCoords,
			crossOrigin: this.prepareCrossOrigin,
			data: this.prepareData,
			dateTime: this.prepareDateTime,
			default: this.prepareDefault,
			defer: this.prepareDefer,
			dir: this.prepareDir,
			disabled: this.prepareDisabled,
			download: this.prepareDownload,
			draggable: this.prepareDraggable,
			encType: this.prepareEncType,
			form: this.prepareForm,
			formAction: this.prepareFormAction,
			formEncType: this.prepareFormEncType,
			formMethod: this.prepareFormMethod,
			formNoValidate: this.prepareFormNoValidate,
			formTarget: this.prepareFormTarget,
			frameBorder: this.prepareFrameBorder,
			headers: this.prepareHeaders,
			height: this.prepareHeight,
			hidden: this.prepareHidden,
			high: this.prepareHigh,
			href: this.prepareHref,
			hrefLang: this.prepareHrefLang,
			htmlFor: this.prepareHtmlFor,
			httpEquiv: this.prepareHttpEquiv,
			id: this.prepareId,
			inputMode: this.prepareInputMode,
			integrity: this.prepareIntegrity,
			is: this.prepareIs,
			isMap: this.prepareIsMap,
			itemProp: this.prepareItemProp,
			keyType: this.prepareKeyType,
			kind: this.prepareKind,
			label: this.prepareLabel,
			lang: this.prepareLang,
			list: this.prepareList,
			loop: this.prepareLoop,
			low: this.prepareLow,
			manifest: this.prepareManifest,
			max: this.prepareMax,
			maxLength: this.prepareMaxLength,
			media: this.prepareMedia,
			method: this.prepareMethod,
			min: this.prepareMin,
			minLength: this.prepareMinLength,
			multiple: this.prepareMultiple,
			muted: this.prepareMuted,
			name: this.prepareName,
			noValidate: this.prepareNoValidate,
			nonce: this.prepareNonce,
			open: this.prepareOpen,
			optimum: this.prepareOptimum,
			pattern: this.preparePattern,
			placeholder: this.preparePlaceholder,
			playsInline: this.preparePlaysInline,
			poster: this.preparePoster,
			preload: this.preparePreload,
			radioGroup: this.prepareRadioGroup,
			readOnly: this.prepareReadOnly,
			rel: this.prepareRel,
			required: this.prepareRequired,
			reversed: this.prepareReversed,
			role: this.prepareRole,
			rowSpan: this.prepareRowSpan,
			rows: this.prepareRows,
		};
		this._cssPreparers = {
			background: this.prepareCssBackground,
			backgroundColor: this.prepareCssBackgroundColor,
			backgroundImage: this.prepareCssBackgroundImage,
			backgroundPosition: this.prepareCssBackgroundPosition,
			backgroundRepeat: this.prepareCssBackgroundRepeat,
			backgroundSize: this.prepareCssBackgroundSize,
			border: this.prepareCssBorder,
			borderBottom: this.prepareCssBorderBottom,
			borderBottomColor: this.prepareCssBorderBottomColor,
			borderBottomStyle: this.prepareCssBorderBottomStyle,
			borderBottomWidth: this.prepareCssBorderBottomWidth,
			borderColor: this.prepareCssBorderColor,
			borderLeft: this.prepareCssBorderLeft,
			borderLeftColor: this.prepareCssBorderLeftColor,
			borderLeftStyle: this.prepareCssBorderLeftStyle,
			borderLeftWidth: this.prepareCssBorderLeftWidth,
			borderRadius: this.prepareCssBorderRadius,
			borderRight: this.prepareCssBorderRight,
			borderRightColor: this.prepareCssBorderRightColor,
			borderRightStyle: this.prepareCssBorderRightStyle,
			borderRightWidth: this.prepareCssBorderRightWidth,
			borderStyle: this.prepareCssBorderStyle,
			borderTop: this.prepareCssBorderTop,
			borderTopColor: this.prepareCssBorderTopColor,
			borderTopStyle: this.prepareCssBorderTopStyle,
			borderTopWidth: this.prepareCssBorderTopWidth,
			borderWidth: this.prepareCssBorderWidth,
			bottom: this.prepareCssBottom,
			boxShadow: this.prepareCssBoxShadow,
			color: this.prepareCssColor,
			cursor: this.prepareCssCursor,
			display: this.prepareCssDisplay,
			flex: this.prepareCssFlex,
			flexBasis: this.prepareCssFlexBasis,
			flexDirection: this.prepareCssFlexDirection,
			flexGrow: this.prepareCssFlexGrow,
			flexShrink: this.prepareCssFlexShrink,
			flexWrap: this.prepareCssFlexWrap,
			float: this.prepareCssFloat,
			font: this.prepareCssFont,
			fontFamily: this.prepareCssFontFamily,
			fontSize: this.prepareCssFontSize,
			fontStyle: this.prepareCssFontStyle,
			fontWeight: this.prepareCssFontWeight,
			height: this.prepareCssHeight,
			justifyContent: this.prepareCssJustifyContent,
			left: this.prepareCssLeft,
			letterSpacing: this.prepareCssLetterSpacing,
			lineHeight: this.prepareCssLineHeight,
			margin: this.prepareCssMargin,
			marginBottom: this.prepareCssMarginBottom,
			marginLeft: this.prepareCssMarginLeft,
			marginRight: this.prepareCssMarginRight,
			marginTop: this.prepareCssMarginTop,
			maxHeight: this.prepareCssMaxHeight,
			maxWidth: this.prepareCssMaxWidth,
			minHeight: this.prepareCssMinHeight,
			minWidth: this.prepareCssMinWidth,
			opacity: this.prepareCssOpacity,
			overflow: this.prepareCssOverflow,
			overflowX: this.prepareCssOverflowX,
			overflowY: this.prepareCssOverflowY,
			padding: this.prepareCssPadding,
			paddingBottom: this.prepareCssPaddingBottom,
			paddingLeft: this.prepareCssPaddingLeft,
			paddingRight: this.prepareCssPaddingRight,
			paddingTop: this.prepareCssPaddingTop,
			position: this.prepareCssPosition,
			right: this.prepareCssRight,
			textAlign: this.prepareCssTextAlign,
		};
	}

	prepareProperty(dom, name, value, oldValue, isSvg) {
		const handler = this._preparers[name];
		if (handler) {
			return handler.call(this, dom, name, value, oldValue, isSvg);
		}
		return { name, value, oldValue, isSvg };
	}

	prepareCssValue(key, value) {
		const handler = this._cssPreparers[key];
		if (handler) {
			return handler.call(this, key, value);
		}
		return value;
	}

	rememberStyle(value, oldValue) {
		this._styleScratch = value;
		this._stylePrev = oldValue;
		return value;
	}

	restoreStyleScratch() {
		return this._styleScratch;
	}

	markStyleCustom(key) {
		this._styleCustom = key != null && key[0] === '-';
		return this._styleCustom;
	}

	takeStyleUnit() {
		return this._styleUnit;
	}

	applyStyleEntry(style, key, value) {
		this._styleScratch = key;
		this._stylePrev = value;
		this.markStyleCustom(key);
		const next = this.prepareCssValue(key, value);
		this.setStyle(style, key, next);
	}

	setStyle(style, key, value) {
		this._styleScratch = key;
		this._stylePrev = value;
		if (key[0] === '-') {
			this._styleCustom = true;
			style.setProperty(key, value);
		} else if (value == null) {
			this._styleCustom = false;
			style[key] = '';
		} else if (typeof value != 'number' || IS_NON_DIMENSIONAL.test(key)) {
			this._styleCustom = false;
			style[key] = value;
		} else {
			this._styleCustom = false;
			style[key] = value + this.takeStyleUnit();
		}
	}

	rememberListener(dom, name, useCapture, value) {
		this._listenerScratch = value;
		this._eventName = name;
		this._captureMode = !!useCapture;
		if (!dom._listeners) dom._listeners = {};
		dom._listeners[name + useCapture] = value;
		return value;
	}

	markCaptureMode(name) {
		this._captureMode = name !== (name = name.replace(/Capture$/, ''));
		this._eventName = name;
		return this._captureMode;
	}

	normalizeListenerName(dom, name) {
		let nameLower = name.toLowerCase();
		if (nameLower in dom) name = nameLower;
		name = name.slice(2);
		this._eventName = name;
		return name;
	}

	bindDomListener(dom, name, useCapture) {
		this._eventName = name;
		this._captureMode = !!useCapture;
		const proxy = useCapture ? eventProxyCapture : eventProxy;
		dom.addEventListener(name, proxy, useCapture);
	}

	unbindDomListener(dom, name, useCapture) {
		this._eventName = name;
		this._captureMode = !!useCapture;
		const proxy = useCapture ? eventProxyCapture : eventProxy;
		dom.removeEventListener(name, proxy, useCapture);
	}

	readListener(dom, name, useCapture) {
		this._eventName = name;
		this._captureMode = !!useCapture;
		return dom._listeners && dom._listeners[name + useCapture];
	}

	rememberAttr(name, value) {
		this._attrName = name;
		this._attrBool = value == null || value === false;
		this._attrNs = '';
		return name;
	}

	markAttrNamespace(name) {
		this._attrName = name;
		if (name !== (name = name.replace(/xlink:?/, ''))) {
			this._attrNs = 'http://www.w3.org/1999/xlink';
		} else {
			this._attrNs = '';
		}
		return name;
	}

	markBooleanAttr(name, value) {
		this._attrName = name;
		this._attrBool =
			value == null || (value === false && !/^ar/.test(name));
		return this._attrBool;
	}

	writeDomProperty(dom, name, value) {
		this._attrName = name;
		this._attrNs = '';
		this._attrBool = value == null;
		dom[name] = value == null ? '' : value;
	}

	writeXLink(dom, name, value) {
		this._attrName = name;
		this._attrNs = 'http://www.w3.org/1999/xlink';
		this._attrBool = value == null || value === false;
		if (this._attrBool) {
			dom.removeAttributeNS(this._attrNs, name.toLowerCase());
		} else {
			dom.setAttributeNS(this._attrNs, name.toLowerCase(), value);
		}
	}

	removeMappedAttr(dom, name) {
		this._attrName = name;
		this._attrBool = true;
		dom.removeAttribute(name);
	}

	setMappedAttr(dom, name, value) {
		this._attrName = name;
		this._attrBool = false;
		dom.setAttribute(name, value);
	}

	writeAttribute(dom, name, value) {
		this.rememberAttr(name, value);
		if (name !== (name = this.markAttrNamespace(name))) {
			this.writeXLink(dom, name, value);
		} else if (this.markBooleanAttr(name, value)) {
			this.removeMappedAttr(dom, name);
		} else {
			this.setMappedAttr(dom, name, value);
		}
	}

	rememberProps(props) {
		this._propScratch = props;
		return props;
	}

	captureKey(key) {
		this._pendingKey = key;
		return key;
	}

	captureRef(ref) {
		this._pendingRef = ref;
		return ref;
	}

	applyDefaultProps(type, normalizedProps) {
		this._propScratch = normalizedProps;
		if (typeof type == 'function' && type.defaultProps != null) {
			for (let i in type.defaultProps) {
				if (normalizedProps[i] === undefined) {
					normalizedProps[i] = type.defaultProps[i];
				}
			}
		}
		return normalizedProps;
	}

	buildElement(type, props, children, args) {
		let normalizedProps = {},
			key,
			ref,
			i;
		this.rememberProps(props);
		for (i in props) {
			if (i == 'key') key = this.captureKey(props[i]);
			else if (i == 'ref') ref = this.captureRef(props[i]);
			else normalizedProps[i] = props[i];
		}

		if (args.length > 3) {
			children = [children];
			for (i = 3; i < args.length; i++) {
				children.push(args[i]);
			}
		}
		if (children != null) {
			normalizedProps.children = children;
		}

		this.applyDefaultProps(type, normalizedProps);
		return this.buildVNode(type, normalizedProps, key, ref, null);
	}

	buildVNode(type, props, key, ref, original) {
		this.rememberProps(props);
		this.captureKey(key);
		this.captureRef(ref);
		const vnode = {
			type,
			props,
			key,
			ref,
			_children: null,
			_parent: null,
			_depth: 0,
			_dom: null,
			_nextDom: undefined,
			_component: null,
			_hydrating: null,
			constructor: undefined,
			_original: original == null ? ++options._vnodeId : original
		};

		if (options.vnode != null) options.vnode(vnode);

		return vnode;
	}

	rememberClone(vnode) {
		this._cloneScratch = vnode && vnode.props;
		return this._cloneScratch;
	}

	captureCloneKey(key) {
		this._cloneKey = key;
		return key;
	}

	captureCloneRef(ref) {
		this._cloneRef = ref;
		return ref;
	}

	copyCloneProps(vnode, props) {
		let normalizedProps = {};
		let source = this.rememberClone(vnode);
		for (let i in source) normalizedProps[i] = source[i];
		this._cloneScratch = normalizedProps;
		this._cloneKey = undefined;
		this._cloneRef = undefined;
		for (let i in props) {
			if (i == 'key') this.captureCloneKey(props[i]);
			else if (i == 'ref') this.captureCloneRef(props[i]);
			else normalizedProps[i] = props[i];
		}
		return normalizedProps;
	}

	appendCloneChildren(normalizedProps, children, args) {
		this._cloneScratch = normalizedProps;
		if (args.length > 3) {
			children = [children];
			for (let i = 3; i < args.length; i++) {
				children.push(args[i]);
			}
		}
		if (children != null) {
			normalizedProps.children = children;
		}
		return normalizedProps;
	}

	mergeCloneElement(vnode, props, children, args) {
		let normalizedProps = this.copyCloneProps(vnode, props);
		normalizedProps = this.appendCloneChildren(
			normalizedProps,
			children,
			args
		);
		this._cloneScratch = normalizedProps;
		return this.buildVNode(
			vnode.type,
			normalizedProps,
			this._cloneKey || vnode.key,
			this._cloneRef || vnode.ref,
			null
		);
	}

	rememberError(error, vnode) {
		this._errorNode = vnode;
		this._errorHandled = false;
		this._errorCtor = error;
		return error;
	}

	markHandled(component) {
		this._errorHandled = !!(component && component._dirty);
		return this._errorHandled;
	}

	walkParents(vnode) {
		this._errorNode = vnode;
		return vnode && vnode._parent;
	}

	invokeHandler(component, error) {
		this._errorCtor = component && component.constructor;
		let handled = false;
		let ctor = this._errorCtor;
		if (ctor && ctor.getDerivedStateFromError != null) {
			component.setState(ctor.getDerivedStateFromError(error));
			handled = component._dirty;
		}
		if (component.componentDidCatch != null) {
			component.componentDidCatch(error);
			handled = component._dirty;
		}
		return this.markHandled({ _dirty: handled });
	}

	traceError(error, vnode) {
		let component, handled;
		const wasHydrating = vnode._hydrating;
		this.rememberError(error, vnode);

		for (; (vnode = this.walkParents(vnode)); ) {
			if ((component = vnode._component) && !component._processingException) {
				try {
					handled = this.invokeHandler(component, error);
					if (handled) {
						vnode._hydrating = wasHydrating;
						return (component._pendingError = component);
					}
				} catch (e) {
					error = e;
					this.rememberError(error, vnode);
				}
			}
		}

		throw error;
	}

	rememberCompat(type, name, value) {
		this._compatType = type;
		this._compatName = name;
		this._compatValue = value;
		return name;
	}

	aliasCompatName(type, name, value, props, onChangeInputType) {
		this.rememberCompat(type, name, value);
		if (name === 'defaultValue' && 'value' in props && props.value == null) {
			name = 'value';
		} else if (name === 'download' && value === true) {
			value = '';
		} else if (/ondoubleclick/i.test(name)) {
			name = 'ondblclick';
		} else if (
			/^onchange(textarea|input)/i.test(name + type) &&
			!onChangeInputType(props.type)
		) {
			name = 'oninput';
		} else if (/^on(Ani|Tra|Tou|BeforeInp)/.test(name)) {
			name = name.toLowerCase();
		} else if (
			/^(?:accent|alignment|arabic|baseline|cap|clip(?!PathU)|color|fill|flood|font|glyph(?!R)|horiz|marker(?!H|W|U)|overline|paint|stop|strikethrough|stroke|text(?!L)|underline|unicode|units|v|vector|vert|word|writing|x(?!C))[A-Z]/.test(
				name
			)
		) {
			name = name.replace(/[A-Z0-9]/, '-$&').toLowerCase();
		} else if (value === null) {
			value = undefined;
		}
		this._compatName = name;
		this._compatValue = value;
		return { name, value };
	}

	coerceCompatValue(value) {
		this._compatValue = value;
		return value;
	}

	normalizeSelectValue(type, props, normalizedProps, toChildArray) {
		this._compatType = type;
		this._compatValue = normalizedProps.value;
		if (
			type == 'select' &&
			normalizedProps.multiple &&
			Array.isArray(normalizedProps.value)
		) {
			normalizedProps.value = toChildArray(props.children).forEach(child => {
				child.props.selected =
					normalizedProps.value.indexOf(child.props.value) != -1;
			});
		}
		if (type == 'select' && normalizedProps.defaultValue != null) {
			normalizedProps.value = toChildArray(props.children).forEach(child => {
				if (normalizedProps.multiple) {
					child.props.selected =
						normalizedProps.defaultValue.indexOf(child.props.value) != -1;
				} else {
					child.props.selected =
						normalizedProps.defaultValue == child.props.value;
				}
			});
		}
		return normalizedProps;
	}

	applyClassNameAlias(type, props, normalizedProps, classNameDescriptor) {
		this._compatType = type;
		this._compatName = 'className';
		if (type && props.class != props.className) {
			classNameDescriptor.enumerable = 'className' in props;
			if (props.className != null) normalizedProps.class = props.className;
			Object.defineProperty(normalizedProps, 'className', classNameDescriptor);
		}
		return normalizedProps;
	}

	normalizeCompatVNode(vnode, helpers) {
		let type = vnode.type;
		let props = vnode.props;
		let normalizedProps = props;
		this.rememberCompat(type, '', props);

		if (typeof type === 'string') {
			normalizedProps = {};
			for (let i in props) {
				let value = props[i];
				const aliased = this.aliasCompatName(
					type,
					i,
					value,
					props,
					helpers.onChangeInputType
				);
				i = aliased.name;
				value = this.coerceCompatValue(aliased.value);
				normalizedProps[i] = value;
			}
			normalizedProps = this.normalizeSelectValue(
				type,
				props,
				normalizedProps,
				helpers.toChildArray
			);
			vnode.props = normalizedProps;
		}

		this.applyClassNameAlias(
			type,
			props,
			normalizedProps,
			helpers.classNameDescriptor
		);
		vnode.$$typeof = helpers.reactElementType;
		return vnode;
	}

	diffAllProps(dom, newProps, oldProps, isSvg, hydrate) {
		let i;

		for (i in oldProps) {
			if (i !== 'children' && i !== 'key' && !(i in newProps)) {
				this.writeProperty(dom, i, null, oldProps[i], isSvg);
			}
		}

		for (i in newProps) {
			if (
				(!hydrate || typeof newProps[i] == 'function') &&
